from __future__ import annotations

import json
from pathlib import Path

from src.application.ports.project_graph_port import ProjectGraphRepository
from src.domain.project_graph.entities import (
    GraphEdge,
    GraphNode,
    NodeKind,
    ProjectGraph,
)

DEFAULT_GRAPH_PATH = Path(__file__).parent / "project_graph" / "project_graph.json"


class JsonProjectGraphRepository(ProjectGraphRepository):
    """Reads the graph generated by ``scripts/build_project_graph.py``."""

    def __init__(self, path: Path = DEFAULT_GRAPH_PATH) -> None:
        self._path = path
        self._graph: ProjectGraph | None = None

    def load(self) -> ProjectGraph:
        if self._graph is None:
            self._graph = self._read()
        return self._graph

    def _read(self) -> ProjectGraph:
        if not self._path.is_file():
            return ProjectGraph()
        payload = json.loads(self._path.read_text(encoding="utf-8"))
        nodes: dict[str, GraphNode] = {}
        for item in payload.get("nodes", []):
            try:
                kind = NodeKind(item["kind"])
            except ValueError:
                continue
            nodes[item["id"]] = GraphNode(
                node_id=item["id"],
                kind=kind,
                name=item["name"],
                description=item.get("description", ""),
                keywords=tuple(item.get("keywords", ())),
                label=item.get("attrs", {}).get("label", ""),
            )
        edges = tuple(
            GraphEdge(
                item["source"],
                item["target"],
                item["relation"],
                item.get("position", 0),
            )
            for item in payload.get("edges", [])
        )
        return ProjectGraph(nodes=nodes, edges=edges)
